CREATE TABLE "PosOperation" ("key" TEXT PRIMARY KEY, "digest" TEXT NOT NULL, "result" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "PosSale" ("key" TEXT PRIMARY KEY, "shopOrderId" TEXT UNIQUE, "customerId" TEXT, "invoiceNumber" TEXT NOT NULL UNIQUE, "totalCents" BIGINT NOT NULL, "status" TEXT NOT NULL, "items" JSONB NOT NULL, "pointsMovementId" TEXT, "ownsPoints" BOOLEAN NOT NULL DEFAULT false, "pointsActive" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
